import React, { useState } from "react";
import { Helmet } from 'react-helmet-async';
import { useNavigate } from 'react-router-dom';
import TextField from '@mui/material/TextField';
import { Typography, Stack, Button } from '@mui/material';
import { axios } from '../utils/axios';
import TinyCmeEditor from "../components/TinyCme/tinyEditor";
import { useMyContext } from "./provider";
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import GoBackButton from '../components/goBackButton/GoBackButton';
import useResponsive from "../hooks/useResponsive";

function EmailTemplate() {
    const navigate = useNavigate();
    const [content, setContent] = useState("");
    const [title, setTitle] = useState("");
    const [desc, setDesc] = useState("");
    const { i18 } = useMyContext();
    const isMobile = useResponsive('down', 'sm')
    const handleEditorChange = (content) => {
        setContent(content);
    };
    const handleTextChange = (value) => {
        setTitle(value)
    }
    const PostTemplate = async () => {
        try {
            const Data = {
                subject: title,
                description: desc,
                body: content
            }
            const res = await axios.post('module/templates/admin/email', Data)
            if (res.status === 201) {
                GenerateToastConfig(res.data.message, 'success');
                backtouser()
            }
            else {
                GenerateToastConfig(res.data.message);
            }
        }
        catch (err) {
            GenerateToastConfig(err?.response?.data?.message);
        }
    }
    const backtouser = () => {
        navigate('/dashboard/Template')
    }
    return (
        <div>
            <Helmet>
                <title>Email Template</title>
            </Helmet>
            <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
                <Typography variant="h4" gutterBottom>
                    {i18?.SETTINGSLIST?.TEMPLATES || "Templates"}
                </Typography>
                <GoBackButton
                    label={i18?.SETTINGSLIST?.GO_BACK || "Go Back"}
                    onClick={backtouser}
                    icon="icon-park-twotone:back"
                />
            </Stack>
            <div style={{
                display: 'flex',
                flexDirection: isMobile ? 'column' : 'column',
                columnGap: isMobile ? '0px' : '0px',
                rowGap: isMobile ? '10px' : '10px',
                marginBottom: '20px',
            }}>
                <TextField
                    id="outlined-basic"
                    label={i18?.SETTINGSLIST?.TITLE || "Title"}
                    variant="outlined"
                    onChange={(e) => handleTextChange(e.target.value)}
                    sx={{ marginRight: !isMobile ? "0px" : "0px" }}
                />
                <TextField
                    id="outlined-basic"
                    label={i18?.SETTINGSLIST?.DESCRIPTION || "Description"}
                    variant="outlined"
                    onChange={(e) => setDesc(e.target.value)}
                    defaultValue={desc}
                />
            </div>
            <TinyCmeEditor value={content} onChange={handleEditorChange} />
            <div style={{ marginTop: '30px' }}>
                <Button variant="contained" onClick={PostTemplate}>{i18?.SETTINGSLIST?.SUBMIT || "Submit"}</Button>
            </div>
        </div>
    )
}

export default EmailTemplate;